* MAIL1 -- Mail dispatch screen
* LISTNAME and CLIENTID are mutually exclusive inputs.
* SUBJECT and BODY are required.
MAP MAIL1 SIZE 24x80
  FIELD HEADER    AT 0,2   LEN 60 PROT BRIGHT COLOR=WHITE
  FIELD USERID    AT 2,20  LEN 8  PROT DIM    COLOR=TURQUOISE
  FIELD LISTNAME  AT 4,20  LEN 40 UNPROT BRIGHT COLOR=WHITE
  FIELD CLIENTID  AT 5,20  LEN 8  UNPROT BRIGHT COLOR=TURQUOISE
  FIELD SUBJECT   AT 7,20  LEN 60 UNPROT BRIGHT COLOR=GREEN
  FIELD BODY      AT 9,5   LEN 70 UNPROT DIM    COLOR=WHITE
  FIELD MESSAGE   AT 15,5  LEN 60 PROT DIM    COLOR=YELLOW
  FIELD FOOTER    AT 23,2  LEN 60 PROT DIM    COLOR=BLUE
ENDMAP
